package com.civicpulse.controller; import com.civicpulse.entity.*;import com.civicpulse.repository.*;import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/reference") public class ReferenceController {private final CategoryRepository categories;private final DepartmentRepository departments;private final UserRepository users;public ReferenceController(CategoryRepository c,DepartmentRepository d,UserRepository u){categories=c;departments=d;users=u;}@GetMapping("/categories") public List<Category> categories(){return categories.findAll();}@GetMapping("/departments") public List<Department> departments(){return departments.findAll();}@GetMapping("/workers") @PreAuthorize("hasAnyRole('OFFICER','ADMIN')") public List<User> workers(){return users.findAll().stream().filter(u->u.getRole()==Role.FIELD_WORKER&&u.isActive()).toList();}}
